window.VO = [{"id":"n01","text":"Your brother is drowning, and he's looking straight at you.","at":0.24,"t0":0.12,"t1":2.705},{"id":"n02","text":"He can't even shout.","at":5.81,"t0":2.905,"t1":4.12},{"id":"n03","text":"You can swim, and he can't. Do you jump in, or call for help?","at":8.74,"t0":4.37,"t1":7.825},{"id":"n04","text":"If you called, help was minutes away, and he had about a minute.","at":18.35,"t0":9.175,"t1":12.48},{"id":"n05","text":"You go home without him.","at":25.76,"t0":12.88,"t1":14.205},{"id":"n06","text":"So you jump.","at":30.61,"t0":15.305,"t1":16.175},{"id":"n07","text":"You've got him.","at":35.35,"t0":17.675,"t1":18.575},{"id":"n08","text":"And then he climbs you.","at":37.99,"t0":18.995,"t1":20.225},{"id":"n09","text":"He'd climb anything, and right now, that's you.","at":40.85,"t0":20.425,"t1":22.765},{"id":"n10","text":"He doesn't even know it's you.","at":46.63,"t0":23.315,"t1":24.775},{"id":"n11","text":"It takes everything you've got to get him to the wall.","at":50.55,"t0":25.275,"t1":27.76},{"id":"n12","text":"You push him up, and he climbs you one last time.","at":56.02,"t0":28.01,"t1":30.735},{"id":"n13","text":"And there's nobody left to push you.","at":62.07,"t0":31.035,"t1":32.765},{"id":"n14","text":"He turns round to look for you.","at":67.23,"t0":33.615,"t1":35.18},{"id":"n15","text":"He made it.","at":71.46,"t0":35.73,"t1":36.56},{"id":"n16","text":"You didn't.","at":73.62,"t0":36.81,"t1":37.625},{"id":"n16b","text":"And some days, neither of you does.","at":75.89,"t0":37.945,"t1":39.965},{"id":"n17","text":"There was a third button.","at":82.03,"t0":41.015,"t1":42.305},{"id":"n18","text":"I just didn't put a number on it.","at":85.11,"t0":42.555,"t1":44.195},{"id":"n19","text":"If you jumped, you dropped it. If you called, it was in your other hand.","at":91.29,"t0":45.645,"t1":49.355},{"id":"n20","text":"It's an empty bottle, and nobody ever told you it could save him.","at":99.11,"t0":49.555,"t1":53.045},{"id":"n21","text":"He'll climb anything that floats, so give him anything but you.","at":106.73,"t0":53.365,"t1":56.465},{"id":"n22","text":"It might not be enough, but now he's got minutes, and you've got your phone.","at":113.53,"t0":56.765,"t1":60.345},{"id":"n23","text":"And he's breathing, and now he knows it's you.","at":121.39,"t0":60.695,"t1":63.055},{"id":"n24","text":"You know who'd jump in for you.","at":127.61,"t0":63.805,"t1":65.25},{"id":"n25","text":"Nobody told them either.","at":131,"t0":65.5,"t1":66.835},{"id":"n26","text":"So tell them.","at":134.17,"t0":67.085,"t1":67.98},{"id":"n27","text":"If I'm ever drowning, don't jump in. Throw something that floats.","at":136.52,"t0":68.26,"t1":71.65}];
